  "substring-with-concatenation-of-all-words": {
    "trick": "All words have the same length, so slide in word-sized steps. Run one window per starting offset (0 … wordLen−1), keeping word counts as you would character counts.",
    "steps": [
      "need = Counter(words).",
      "For each offset, move r in steps of wordLen and add the word to the window counts.",
      "A word not in need resets the window. Too many copies → shrink from the left.",
      "When the window holds exactly k words, record l and slide forward one word."
    ],
    "time": "O(n · wordLen)",
    "space": "O(k)",
    "pitfall": "Restarting the scan at every index (O(n·k·wordLen)), and forgetting that the word list can contain duplicates.",
    "code": "class Solution:\n    def findSubstring(self, s: str, words: List[str]) -> List[int]:\n        wl, k = len(words[0]), len(words)\n        need = Counter(words)\n        res = []\n        for off in range(wl):\n            l, seen, count = off, Counter(), 0\n            for r in range(off, len(s) - wl + 1, wl):\n                w = s[r:r + wl]\n                if w not in need:\n                    seen.clear()\n                    count, l = 0, r + wl\n                    continue\n                seen[w] += 1\n                count += 1\n                while seen[w] > need[w]:\n                    seen[s[l:l + wl]] -= 1\n                    count -= 1\n                    l += wl\n                if count == k:\n                    res.append(l)\n                    seen[s[l:l + wl]] -= 1\n                    count -= 1\n                    l += wl\n        return res"
  },
  "minimum-window-substring": {
    "trick": "Expand right until the window contains everything (missing == 0), then shrink from the left while it still does. Record the window, break validity, and keep expanding.",
    "steps": [
      "need = Counter(t), missing = len(t).",
      "Expand: if need[ch] > 0, decrement missing. Always decrement need[ch].",
      "When missing == 0, drop surplus characters from the left (need < 0), record the window, then release s[l] to look for a smaller one."
    ],
    "time": "O(|s| + |t|)",
    "space": "O(alphabet)",
    "pitfall": "Comparing whole count maps at every step is O(52·n). A single 'missing' counter keeps it O(n).",
    "code": "class Solution:\n    def minWindow(self, s: str, t: str) -> str:\n        need = Counter(t)\n        missing = len(t)\n        l = start = 0\n        end = float(\"inf\")\n        for r, ch in enumerate(s):\n            if need[ch] > 0:\n                missing -= 1\n            need[ch] -= 1\n            if missing == 0:\n                while need[s[l]] < 0:\n                    need[s[l]] += 1\n                    l += 1\n                if r - l < end - start:\n                    start, end = l, r\n                need[s[l]] += 1\n                missing += 1\n                l += 1\n        return \"\" if end == float(\"inf\") else s[start:end + 1]"
  },
