  "game-of-life": {
    "trick": "Store the next state in a spare bit: bit 0 = current, bit 1 = next. Neighbours read bit 0, so updates don't interfere. Shift right at the end.",
    "steps": [
      "Count live neighbours using cell & 1.",
      "If the cell lives in the next generation, set bit 1 (cell |= 2).",
      "Shift every cell right by one."
    ],
    "time": "O(m·n)",
    "space": "O(1)",
    "pitfall": "Updating cells directly means later cells see next-generation neighbours.",
    "code": "class Solution:\n    def gameOfLife(self, board: List[List[int]]) -> None:\n        m, n = len(board), len(board[0])\n        for r in range(m):\n            for c in range(n):\n                live = 0\n                for dr in (-1, 0, 1):\n                    for dc in (-1, 0, 1):\n                        if (dr or dc) and 0 <= r + dr < m and 0 <= c + dc < n:\n                            live += board[r + dr][c + dc] & 1\n                alive = board[r][c] & 1\n                if (alive and live in (2, 3)) or (not alive and live == 3):\n                    board[r][c] |= 2\n        for r in range(m):\n            for c in range(n):\n                board[r][c] >>= 1"
  },
