    "space": "O(1)",
    "pitfall": "Reversing a final partial group. It must be left as is.",
    "code": "class Solution:\n    def reverseKGroup(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:\n        dummy = ListNode(0, head)\n        group_prev = dummy\n        while True:\n            kth = group_prev\n            for _ in range(k):\n                kth = kth.next\n                if not kth:\n                    return dummy.next\n            group_next = kth.next\n            prev, cur = group_next, group_prev.next\n            while cur is not group_next:\n                cur.next, prev, cur = prev, cur, cur.next\n            first = group_prev.next\n            group_prev.next = kth\n            group_prev = first"
