    "code": "class Solution:\n    def rotateRight(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:\n        if not head:\n            return head\n        n, tail = 1, head\n        while tail.next:\n            tail = tail.next\n            n += 1\n        k %= n\n        if k == 0:\n            return head\n        tail.next = head\n        new_tail = head\n        for _ in range(n - k - 1):\n            new_tail = new_tail.next\n        new_head = new_tail.next\n        new_tail.next = None\n        return new_head"
