    "code": "class Solution:\n    def permute(self, nums: List[int]) -> List[List[int]]:\n        res, path, used = [], [], [False] * len(nums)\n\n        def bt():\n            if len(path) == len(nums):\n                res.append(path[:])\n                return\n            for i, x in enumerate(nums):\n                if not used[i]:\n                    used[i] = True\n                    path.append(x)\n                    bt()\n                    path.pop()\n                    used[i] = False\n\n        bt()\n        return res"
