    "code": "class Solution:\n    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:\n        candidates.sort()\n        res, path = [], []\n\n        def bt(start, remain):\n            if remain == 0:\n                res.append(path[:])\n                return\n            for i in range(start, len(candidates)):\n                c = candidates[i]\n                if c > remain:\n                    break\n                path.append(c)\n                bt(i, remain - c)\n                path.pop()\n\n        bt(0, target)\n        return res"
