    "code": "class Solution:\n    def addBinary(self, a: str, b: str) -> str:\n        i, j, carry, out = len(a) - 1, len(b) - 1, 0, []\n        while i >= 0 or j >= 0 or carry:\n            s = carry\n            if i >= 0:\n                s += int(a[i])\n                i -= 1\n            if j >= 0:\n                s += int(b[j])\n                j -= 1\n            out.append(str(s % 2))\n            carry = s // 2\n        return \"\".join(reversed(out))"
